abhinav_17_19 = {
    'hi': '।।8.17--8.19।। श्री अभिनवगुप्त कहते हैं: जो सहस्र-युग पर्यन्त चलने वाले ब्रह्मा के दिन और सहस्र-युग पर्यन्त चलने वाली रात्रि का ज्ञान रखते हैं, वे कालतत्त्ववेत्ता हैं। दिन के आगमन पर अव्यक्त (ब्रह्मा की सुप्त अवस्था) से सर्व प्राणी प्रादुर्भूत होते हैं और रात्रि के आगमन पर उसी अव्यक्त में विलीन होते हैं; इस प्रकार सर्व प्राणी कर्म-परवश होकर पुनरपि उत्पन्न व लीन होते रहते हैं।',
    'en': '8.17--8.19 Sri Abhinavagupta states: Those who know Brahma\"s day lasting a thousand yugas and night lasting a thousand yugas are truly knowers of cosmic time. At daybreak, all beings manifest from the unmanifest (Brahma\"s subtle state); at nightfall, they dissolve back into it. Thus the multitude of beings, helpless under karma, repeatedly emerge and dissolve.',
    'be': '৮.১৭--৮.১৯ শ্রী অভিনবগুপ্ত বলেছেন: যে সহস্র-যুগ পর্যন্ত চলা ব্রহ্মার দিন এবং সহস্র-যুগ পর্যন্ত চলা রাত্রির জ্ঞান রাখে, তারা কালতত্ত্ববেত্তা। দিনের আগমনে অব্যক্ত (ব্রহ্মার সুপ্ত অবস্থা) থেকে সর্ব প্রাণী প্রাদুর্ভূত হয় এবং রাত্রির আগমনে সেই অব্যক্তেই বিলীন হয়; এই ভাবে সর্ব প্রাণী কর্ম-পরবশ হয়ে পুনরায় উৎপন্ন ও লীন হতে থাকে।',
    'ka': '೮.೧೭--೮.೧೯ ಶ್ರೀ ಅಭಿನವಗುಪ್ತರು ಹೇಳುತ್ತಾರೆ: ಯಾರು ಸಹಸ್ರಯುಗಗಳವರೆಗೆ ನಡೆಯುವ ಬ್ರಹ್ಮನ ಹಗಲು ಹಾಗೂ ಸಹಸ್ರಯುಗಗಳವರೆಗೆ ನಡೆಯುವ ರಾತ್ರಿಯ ಜ್ಞಾನವನ್ನು ಹೊಂದಿದ್ದಾರೋ, ಅವರು ಕಾಲತತ್ತ್ವವೇತ್ತರು. ಹಗಲಿನ ಆಗಮನದಲ್ಲಿ ಅವ್ಯಕ್ತದಿಂದ (ಬ್ರಹ್ಮನ ಸುಪ್ತಾವಸ್ಥೆ) ಸರ್ವಪ್ರಾಣಿಗಳೂ ಪ್ರಕಟವಾಗುತ್ತವೆ ಹಾಗೂ ರಾತ್ರಿಯ ಆಗಮನದಲ್ಲಿ ಅದೇ ಅವ್ಯಕ್ತದಲ್ಲಿ ಲೀನವಾಗುತ್ತವೆ; ಈ ರೀತಿ ಸರ್ವಪ್ರಾಣಿಗಳೂ ಕರ್ಮಪರವಶವಾಗಿ ಮರಳಿ ಮರಳಿ ಉತ್ಪನ್ನವೂ ಲೀನವೂ ಆಗುತ್ತಿರುತ್ತವೆ'
}

madhav_17_19 = {
    'hi': '।।8.17--8.19।। श्री मध्वाचार्य कहते हैं: ब्रह्मा का एक दिन सहस्र महायुग का होता है और उतनी ही रात्रि होती है। प्रलयकाल में सर्व जगत् ब्रह्मा के अव्यक्त स्वरूप में विलीन हो जाता है और पुनः सृष्टिकाल में प्रादुर्भूत होता है; किंतु विष्णु का परम पद इस सर्व चक्र से परे नित्य है।',
    'en': '8.17--8.19 Sri Madhavacharya states: A single day of Brahma spans a thousand mahayugas, and his night is of equal duration. At cosmic dissolution, all worlds merge into Brahma\"s unmanifest state and emerge again; yet Lord Vishnu\"s supreme realm remains eternal beyond this cycle.',
    'be': '৮.১৭--৮.১৯ শ্রী মধ্বাচার্য বলেছেন: ব্রহ্মার এক দিন সহস্র মহাযুগের হয় এবং ততটাই রাত্রি হয়। প্রলয়কালে সর্ব জগৎ ব্রহ্মার অব্যক্ত রূপে বিলীন হয়ে যায় এবং পুনরায় সৃষ্টিকালে প্রাদুর্ভূত হয়; কিন্তু বিষ্ণুর পরম পদ এই সর্ব চক্র থেকে পরে নিত্য।',
    'ka': '೮.೧೭--೮.೧೯ ಶ್ರೀ ಮಧ್ವಾಚಾರ್ಯರು ಹೇಳುತ್ತಾರೆ: ಬ್ರಹ್ಮನ ಒಂದು ಹಗಲು ಸಹಸ್ರ ಮಹಾಯುಗದ್ದಾಗಿರುತ್ತದೆ ಹಾಗೂ ಅಷ್ಟೇ ರಾತ್ರಿಯಿರುತ್ತದೆ. ಪ್ರಲಯಕಾಲದಲ್ಲಿ ಸರ್ವ ಜಗತ್ತೂ ಬ್ರಹ್ಮನ ಅವ್ಯಕ್ತಸ್ವರೂಪದಲ್ಲಿ ಲೀನವಾಗುತ್ತದೆ ಹಾಗೂ ಮತ್ತೆ ಸೃಷ್ಟಿಕಾಲದಲ್ಲಿ ಪ್ರಕಟವಾಗುತ್ತದೆ; ಆದರೆ ವಿಷ್ಣುವಿನ ಪರಮಪದವು ಈ ಸರ್ವ ಚಕ್ರಕ್ಕಿಂತಲೂ ಅತೀತವಾಗಿ ನಿತ್ಯವಾಗಿರುತ್ತದೆ'
}

jaya_17_19 = {
    'hi': '।।8.17--8.19।। श्री जयतीर्थ कहते हैं: ब्रह्मा के अहोरात्र का मान काल की सीमा को दर्शाता है; प्राकृत सृष्टि और प्रलय का यह चक्र जीव की परवशता दिखाता है, जबकि भगवद्धाम नित्य व अपुनरावृत्ति-प्रद है।',
    'en': '8.17--8.19 Sri Jayatirtha states: The duration of Brahma\"s day and night reveals the limit of cosmic time; the cycle of creation and dissolution demonstrates the helplessness of souls, whereas the Lord\"s realm is eternal and non-returning.',
    'be': '৮.১৭--৮.১৯ শ্রী জয়তীর্থ বলেছেন: ব্রহ্মার অহোরাত্রের মান কালের সীমাকে দেখায়; প্রাকৃত সৃষ্টি ও প্রলয়ের এই চক্র জীবের পরবশতা দেখায়, যেখানে ভগবদ্ ধাম নিত্য ও অপুনরাবৃত্তি-প্রদ।',
    'ka': '೮.೧೭--೮.೧೯ ಶ್ರೀ ಜಯತೀರ್ಥರು ಹೇಳುತ್ತಾರೆ: ಬ್ರಹ್ಮನ ಅಹೋರಾತ್ರಿಯ ಮಾನವು ಕಾಲದ ಗಡಿಯನ್ನು ತೋರಿಸುತ್ತದೆ; ಪ್ರಾಕೃತ ಸೃಷ್ಟಿ ಹಾಗೂ ಪ್ರಲಯಗಳ ಈ ಚಕ್ರವು ಜೀವಿಯ ಪರವಶತೆಯನ್ನು ತೋರಿಸುತ್ತದೆ, ಆದರೆ ಭಗವದ್ಧಾಮವು ನಿತ್ಯವೂ ಅಪುನರಾವೃತ್ತಿಪ್ರದವೂ ಆಗಿದೆ'
}

abhinav_20_22 = {
    'hi': '।।8.20--8.22।। श्री अभिनवगुप्त कहते हैं: उस अव्यक्त से भी परे सनातन अव्यक्त परमेश्वर तत्त्व है, जो सर्व भूतों के विनष्ट होने पर भी कभी नष्ट नहीं होता। वही अक्षर और परम गति कहा जाता है, जिसे प्राप्त करके जीव पुनः संसार में नहीं लौटता; वह परम पुरुष अनन्य भक्ति से प्राप्त होने योग्य है।',
    'en': '8.20--8.22 Sri Abhinavagupta states: Superior to that unmanifest is the Eternal Unmanifest Supreme Lord, who perishes not even when all beings perish. That is declared as the Imperishable and Supreme Goal, attaining which souls return not; that Supreme Person is reachable through exclusive devotion.',
    'be': '৮.২০--৮.২২ শ্রী অভিনবগুপ্ত বলেছেন: সেই অব্যক্ত থেকেও পরে সনাতন অব্যক্ত পরমেশ্বর তত্ত্ব, যা সর্ব ভূতের বিনষ্ট হওয়া সত্ত্বেও কখনো নষ্ট হয় না। সেটাই অক্ষর এবং পরম গতি বলা হয়, যা প্রাপ্ত হয়ে জীব পুনরায় সংসারে ফেরে না; সেই পরম পুরুষ অনন্য ভক্তিতে প্রাপ্ত হওয়ার যোগ্য।',
    'ka': '೮.೨೦--೮.೨೨ ಶ್ರೀ ಅಭಿನವಗುಪ್ತರು ಹೇಳುತ್ತಾರೆ: ಆ ಅವ್ಯಕ್ತಕ್ಕಿಂತಲೂ ಅತೀತವಾದದ್ದು ಸನಾತನ ಅವ್ಯಕ್ತ ಪರಮೇಶ್ವರತತ್ತ್ವವಾಗಿದೆ, ಇದು ಸರ್ವಭೂತಗಳೂ ವಿನಾಶಗೊಂಡರೂ ಎಂದಿಗೂ ನಾಶವಾಗುವುದಿಲ್ಲ. ಅದನ್ನೇ ಅಕ್ಷರ ಹಾಗೂ ಪರಮ ಗತಿ ಎನ್ನಲಾಗುತ್ತದೆ, ಅದನ್ನು ಪಡೆದು ಜೀವಿಯು ಮತ್ತೆ ಸಂಸಾರಕ್ಕೆ ಮರಳುವುದಿಲ್ಲ; ಆ ಪರಮಪುರುಷನು ಅನನ್ಯಭಕ್ತಿಯಿಂದ ಪಡೆಯಲು ಯೋಗ್ಯನಾಗಿದ್ದಾನೆ'
}

madhav_20_21 = {
    'hi': '।।8.20--8.21।। श्री मध्वाचार्य कहते हैं: प्रकृति और ब्रह्मा से भी परे सनातन अव्यक्त भगवान् वासुदेव हैं; सर्व भूतों के प्रलय में भी उनका परम धाम अनामय व अविनाशी रहता है, वही जीवों का परम लक्ष्य है।',
    'en': '8.20--8.21 Sri Madhavacharya states: Superior even to Prakriti and Brahma is Eternal Unmanifest Lord Vasudeva; even during universal dissolution, His supreme abode remains imperishable, which is the ultimate goal of all souls.',
    'be': '৮.২০--৮.২১ শ্রী মধ্বাচার্য বলেছেন: প্রকৃতি এবং ব্রহ্মা থেকেও পরে সনাতন অব্যক্ত ভগবান বাসুদেব; সর্ব ভূতের প্রলয়েও তাঁর পরম ধাম অনাময় ও অবিনাশী থাকে, সেটাই জীবের পরম লক্ষ্য।',
    'ka': '೮.೨೦--೮.೨೧ ಶ್ರೀ ಮಧ್ವಾಚಾರ್ಯರು ಹೇಳುತ್ತಾರೆ: ಪ್ರಕೃತಿ ಹಾಗೂ ಬ್ರಹ್ಮನಿಂದಲೂ ಅತೀತನಾದವನು ಸನಾತನ ಅವ್ಯಕ್ತನಾದ ಭಗವಾನ್ ವಾಸುದೇವನಾಗಿದ್ದಾನೆ; ಸರ್ವಭೂತಗಳ ಪ್ರಲಯದಲ್ಲೂ ಆತನ ಪರಮಧಾಮವು ಅನಾಮಯವೂ ಅವಿನಾಶಿಯೂ ಆಗಿರುತ್ತದೆ, ಅದೇ ಜೀವಿಗಳ ಪರಮ ಗುರಿಯಾಗಿದೆ'
}

jaya_20_21 = {
    'hi': '।।8.20--8.21।। श्री जयतीर्थ कहते हैं: "परस्तस्मात्तु भावोऽन्यः"—प्रकृति-कारण से विलक्षण परम पुरुष विष्णु ही "अव्यक्त" और "अक्षर" कहलाते हैं, जिनका परम धाम नित्य-मुक्ति रूप है।',
    'en': '8.20--8.21 Sri Jayatirtha states: "Distinct from that is another eternal state"—Lord Vishnu, distinct from cosmic unmanifest cause, is called Unmanifest and Imperishable, whose supreme abode is eternal Mukti.',
    'be': '৮.২০--৮.২১ শ্রী জয়তীর্থ বলেছেন: "পরস্তস্মাত্তু ভাবোঽন্যঃ"—প্রকৃতি-কারণ থেকে বিলক্ষণ পরম পুরুষ বিষ্ণুই "অব্যক্ত" এবং "অক্ষর" নামে পরিচিত, যাঁর পরম ধাম নিত্য-মুক্তি রূপ।',
    'ka': '೮.೨೦--೮.೨೧ ಶ್ರೀ ಜಯತೀರ್ಥರು ಹೇಳುತ್ತಾರೆ: "ಪರಸ್ತಸ್ಮಾತ್ತು ಭಾವೋಽನ್ಯಃ"—ಪ್ರಕೃತಿಕಾರಣಕ್ಕಿಂತಲೂ ವಿಲಕ್ಷಣನಾದ ಪರಮಪುರುಷ ವಿಷ್ಣುವೇ "ಅವ್ಯಕ್ತ" ಹಾಗೂ "ಅಕ್ಷರ" ಎನಿಸುತ್ತಾನೆ, ಆತನ ಪರಮಧಾಮವು ನಿತ್ಯಮುಕ್ತಿರೂಪವಾಗಿದೆ'
}

